#!/usr/bin/env python3
"""patch_site_surfaces.py -- Lot says where dressing may go.

Lot 0.44.0 -> 0.45.0. Piece 2 of 5 in the Layer 3 chain
(`docs/SURFACE_DRESSING.md` section 2). Piece 1 was Zoo 0.38.0, which made a
species requestable by name.

WHY THIS IS LOT'S JOB AND NOT THE PLANNER'S.

`level_factory/schemas/surface_dressing.v1.json` decides it, in three places:

    zones       "Semantic regions from Deli Counter / Lot -- not invented here."
    traversed   "taken from Lot's walkable surfaces, not asserted by the
                 dressing planner."
    exclusions  "Every entry must name what declared it; an exclusion nobody
                 declared is a preference."

So `lot/site_surfaces.py` answers, and its rule is that every zone traces to a
key in the site spec and every number to a module that already derived it:

    ground        open ground, via site_extent.resolve
    paths         a gameplay_path corridor per path, at its own width
    courtyards    a play_space zone each, at their own size
    buildings     a wall_base band one agent radius wide, from the nav bake
    perimeter     everything outside site_extent.required_rect
    cover         cover_edge exclusions at site_cover.MARKER_CLEARANCE
    spawn/objective/extraction   exclusions on the named buildings

`capsule_block()` carries `unassisted_step_max` from
`site_steps.unassisted_step_max_m` -- 0.11716 m for a 0.4 m capsule at 45
degrees -- and every zone box is capped at exactly that height, so a later
gate checks the honesty rule instead of re-deriving it.

THE BUG THIS MODULE WAS REWRITTEN FOR, KEPT AS A TEST.

The first version emitted one AABB per path. Run against the real
`coldrun_pawn_job` spec, three diagonal 5 m paths produced boxes of 1,935 m2
each -- 12% of a 16,500 m2 site apiece -- and nearly every square metre of the
site came back `gameplay_path`. That is the STRICTEST visibility class, so the
whole site would have been dressed to the tightest budget and the density
variation the guide asks for (sidewalk centre low, wall seam high, abandoned
corner very high) would have collapsed into one uniform sparse scatter: the
flat procedural read the layer exists to avoid, arrived at by being careful.

Corridors now ship as `width x width` boxes stepped along the centreline at
half a width, which cannot leave a gap.
`test_a_diagonal_path_does_not_swallow_the_site` caps a path zone at 1% of the
site and fails the old construction outright (12% vs 1%).

The perimeter is an annulus and ships as the four strips it is made of, for
the same reason.

WHAT IT REFUSES TO GUESS. A raw site spec carries no building footprint --
that annotation comes from `merge_gameplay` -- so wall bases cannot be
computed from one. Rather than emit no wall-base zones, which looks exactly
like a site with no walls, it emits `LOT_SURFACE_FOOTPRINT_UNKNOWN` naming
every building it could not read.

VERIFIED: 29 tests, on the real coldrun_pawn_job shape. This patch adds only
new files plus VERSION and CHANGELOG; it changes no existing Lot behaviour and
nothing else imports it yet.

    python patch_site_surfaces.py --check
    python patch_site_surfaces.py --selftest
    python patch_site_surfaces.py
    python patch_site_surfaces.py --revert
"""
