def repo_root(start=None):
    d = os.path.abspath(start or os.path.dirname(os.path.abspath(__file__)))
    for _ in range(8):
        if (os.path.isdir(os.path.join(d, "lot"))
                and os.path.isfile(os.path.join(d, "lot", "site_extent.py"))):
            return d
        nd = os.path.dirname(d)
        if nd == d:
            break
        d = nd
    return None


def sha(b):
    return hashlib.sha256(b).hexdigest()


def rd(p):
    with open(p, "rb") as fh:
        return fh.read()


def wr(p, b):
    os.makedirs(os.path.dirname(p), exist_ok=True)
    with open(p, "wb") as fh:
        fh.write(b)


def plan(root):
    rows, ok = [], True
    for rel, d in PAYLOAD.items():
        p = os.path.join(root, rel.replace("/", os.sep))
        exists = os.path.isfile(p)
        if d["kind"] == "new":
            if exists and sha(rd(p)) == d["post_sha"]:
                rows.append((rel, "already-current", True))
            elif exists:
                rows.append((rel, "EXISTS AND DIFFERS - refusing", False))
                ok = False
            else:
                rows.append((rel, f"create {d['post_bytes']} B", True))
            continue
        if not exists:
            rows.append((rel, "MISSING - refusing", False))
            ok = False
            continue
        cur = sha(rd(p))
        if cur == d["post_sha"]:
            rows.append((rel, "already-current", True))
        elif cur == d["pre_sha"]:
            rows.append((rel, f"replace {d['pre_bytes']} -> {d['post_bytes']} B",
                         True))
        else:
            rows.append((rel, f"DRIFT sha {cur[:12]} != {d['pre_sha'][:12]}",
                         False))
            ok = False
    return ok, rows


def show(rows):
    w = max(len(r[0]) for r in rows)
    for rel, msg, good in rows:
        print(f"  {'ok ' if good else 'STOP'}  {rel:<{w}}  {msg}")


def apply(root):
    ok, rows = plan(root)
    show(rows)
    if not ok:
        print("\nREFUSING: nothing written. Resolve the lines marked STOP.")
        return 1
    n = 0
    for rel, d in PAYLOAD.items():
        p = os.path.join(root, rel.replace("/", os.sep))
        if os.path.isfile(p):
            cur = rd(p)
            if sha(cur) == d["post_sha"]:
                continue
            side = p + SIDECAR
            if not os.path.exists(side):
                wr(side, cur)
        wr(p, base64.b64decode(d["b64"]))
        assert sha(rd(p)) == d["post_sha"], rel
        n += 1
    print(f"\nWROTE {n} file(s). Sidecars: *{SIDECAR}")
    print("Next:")
    print("  cd lot")
    print("  python -m pytest tests/test_site_surfaces.py -q")
    print("  python -m pytest tests -q")
    print("29 new tests. Nothing existing imports site_surfaces yet, so the")
    print("rest of the Lot suite should be exactly as you left it.")
    return 0


def revert(root):
    n = 0
    for rel, d in PAYLOAD.items():
        p = os.path.join(root, rel.replace("/", os.sep))
        side = p + SIDECAR
        if os.path.exists(side):
            wr(p, rd(side))
            os.remove(side)
            print(f"  reverted {rel}")
            n += 1
        elif d["kind"] == "new" and os.path.isfile(p):
            if sha(rd(p)) == d["post_sha"]:
                os.remove(p)
                print(f"  removed  {rel} (this patch created it)")
                n += 1
            else:
                print(f"  KEPT     {rel} (modified since; not ours to delete)")
    print(f"reverted {n} file(s)")
    return 0


def selftest():
    bad = 0

    def fail(msg):
        nonlocal bad
        print(f"  FAIL  {msg}")
        bad += 1

    print("patch_site_surfaces selftest")

    for rel, d in PAYLOAD.items():
        b = base64.b64decode(d["b64"])
        if sha(b) != d["post_sha"] or len(b) != d["post_bytes"]:
            fail(f"payload {rel} does not match its recorded hash/size")
    print(f"  ok    {len(PAYLOAD)} payloads decode to their recorded hashes")

    mod = base64.b64decode(
        PAYLOAD["lot/site_surfaces.py"]["b64"]).decode("utf-8")
    tst = base64.b64decode(
        PAYLOAD["lot/tests/test_site_surfaces.py"]["b64"]).decode("utf-8")

    import ast
    tree = ast.parse(mod)
    funcs = {n.name for n in tree.body if isinstance(n, ast.FunctionDef)}
    for want in ("zones", "exclusions", "surfaces", "zone_for", "excluded",
                 "capsule_block", "corridor_boxes", "wall_base_band_m"):
        if want not in funcs:
            fail(f"site_surfaces has no {want}()")
    print(f"  ok    the module exposes its {len(funcs)} functions "
          "including zone_for and excluded")

    # Lot modules are FLAT -- no package, tests do sys.path.insert and
    # `import site_extent`. A relative import here would import cleanly in a
    # sandbox and ImportError on the real tree, which is how this nearly
    # shipped.
    if "from . import" in mod:
        fail("site_surfaces uses a relative import; lot/ is not a package")
    for want in ("import site_cover", "import site_extent", "import site_steps"):
        if want not in mod:
            fail(f"site_surfaces does not `{want}`")
    print("  ok    flat imports, matching how lot/ is actually laid out")

    # FALSIFICATION: the numbers must be BORROWED, not written down. If the
    # module carries a literal 0.117 it has copied the honesty rule instead of
    # deriving it, and the copy will not move when the capsule does.
    # Look at CODE, not text: the module discusses 0.11716 in a comment about
    # rounding, and a substring search called that a copied constant. A check
    # that fires on prose gets switched off, which is worse than not having it.
    copied = [n.value for n in ast.walk(tree)
              if isinstance(n, ast.Constant) and isinstance(n.value, float)
              and 0.11 < n.value < 0.125]
    if copied:
        fail(f"site_surfaces hard-codes the step limit {copied} -- it must "
             "come from site_steps.unassisted_step_max_m, not a copy")
    if "unassisted_step_max_m" not in mod:
        fail("site_surfaces never calls site_steps.unassisted_step_max_m")
    if "MARKER_CLEARANCE" not in mod:
        fail("exclusion radii are not site_cover's MARKER_CLEARANCE")
    print("  ok    step limit and clearances are derived, not copied")

    # The corridor regression must be pinned by a test, not just fixed.
    if "swallow_the_site" not in tst:
        fail("no test pins the corridor-swallows-the-site regression")
    if "corridor_boxes" not in mod:
        fail("corridors are not segmented")
    print("  ok    the corridor regression is pinned by a named test")

    # And the module must not quietly stop reporting unreadable footprints.
    if "CODE_FOOTPRINT_UNKNOWN" not in mod or \
            "CODE_FOOTPRINT_UNKNOWN" not in tst:
        fail("unreadable footprints are not reported, or not tested")
    print("  ok    unreadable footprints are reported and the report is tested")

    ver = base64.b64decode(PAYLOAD["lot/VERSION"]["b64"]).decode("utf-8")
    if ver.strip() != "Lot 0.45.0":
        fail(f"VERSION payload is {ver.strip()!r}")
    ch = base64.b64decode(PAYLOAD["lot/CHANGELOG.md"]["b64"]).decode("utf-8")
    if not ch.startswith("## [0.45.0]") or "## [0.44.0]" not in ch:
        fail("CHANGELOG payload is not 0.45.0 on top of 0.44.0")
    print("  ok    VERSION 0.45.0 and a CHANGELOG that keeps its history")

    ref = base64.b64decode(next(iter(PAYLOAD.values()))["b64"])
    mut = bytearray(ref)
    mut[len(mut) // 2] ^= 0x20
    if sha(bytes(mut)) == sha(ref):
        fail("a mutated payload hashed identically")
    else:
        print("  ok    one flipped byte changes the hash")

    print("SELFTEST", "PASSED" if bad == 0 else f"FAILED ({bad})")
    return 1 if bad else 0


def main(argv):
    if "--selftest" in argv:
        return selftest()
    root = None
    if "--root" in argv:
        root = os.path.abspath(argv[argv.index("--root") + 1])
    root = root or repo_root()
    if not root:
        print("Could not find the gabagool_factory root. Pass --root <path>.")
        return 2
    print(f"repo root: {root}")
    if "--revert" in argv:
        return revert(root)
    ok, rows = plan(root)
    if "--check" in argv:
        show(rows)
        print("\n--check only: nothing written."
              + ("" if ok else "  RESOLVE THE STOP LINES FIRST."))
        return 0 if ok else 1
    return apply(root)


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
